import { addSection8Visual } from "./course-v3-section8-visuals.mjs";
import { section8Databases as databases, section8SqlCases as sql, section8Ddl as ddl } from "./course-v3-section8-sql.mjs";

// Authored S8 teaching and lesson assessments, with explicit objective ownership.
const ids = (r, ...n) => n.map((i) => `${r}.A${String(i).padStart(2, "0")}`);
const objectives = (r, descriptions) => descriptions.map((s, i) => [ids(r, i + 1)[0], s]);
const table = (title, headers, rows) => ({ type: "table", title, headers, rows, preserveText: true });
const flow = (title, steps) => ({ type: "flow", title, steps, preserveText: true });
const worked = (title, steps) => ({ type: "worked-example", title, steps });
const dataTable = (database, n = 0) => ({ ...databases[database].tables[n], type: "table", preserveText: true });
const resultTable = (key) => table("Expected result", sql[key].headers, sql[key].expectedRows);
const queryExample = (key, title, reasoning) => worked(title, [["Read the task", reasoning], ["Write SQL", sql[key].sql], ["Check the result", sql[key].expectedRows.map((r) => r.join(" | ")).join("\n")]]);
const unit = (key, heading, objectiveIds, explanation, materials, misconception, prompt, answer) => ({
  unitKey: key, syllabusId: objectiveIds[0].replace(/\.A\d+$/, ""), heading, objectiveIds, explanation,
  materials: materials.map((m) => ({ ...m, objectiveIds })), misconceptions: [misconception],
  checkpoint: { prompt, answer }, useAuthoredVisual: true, preserveTeachingSteps: true,
});
const question = (id, prompt, objectiveIds, answerPoints, commonError, extra = {}) => ({
  id, prompt, objectiveIds, answerPoints, commonError, marks: answerPoints.length,
  type: "Application", authored: true, ...extra,
});
const practice = (l, n, ...args) => question(`S8-L0${l}-Q${n}`, ...args);
const exam = (l, n, ...args) => question(`S8-L0${l}-EXAM-${n}`, ...args);
const sqlAnswer = (key) => ({ sqlCase: key, answerCode: sql[key].sql, ...(sql[key].headers ? { answerTable: resultTable(key) } : {}) });

const concepts = {
  title: "From file-based systems to relational databases",
  subtitle: "Connect file-based problems to relational mechanisms, then identify records, keys, relationships and indexes.",
  guidingQuestion: "How can a clinic update a patient's address once and keep related records consistent?",
  diagnostic: { prompt: "An address appears in three separate application files. Only one copy is changed. What can go wrong?", answer: "The files can disagree about the patient's current address; the repeated copies have become inconsistent." },
  objectives: [
    ...objectives("S8.01", ["Explain limitations of a file-based approach to storing and retrieving data.", "Describe relational features that address particular file-based limitations."]),
    ...objectives("S8.02", ["Use entity, table, record, tuple, field and attribute correctly.", "Distinguish primary, candidate, secondary and foreign keys.", "Explain one-to-one, one-to-many and many-to-many relationships.", "Explain and apply referential integrity.", "Explain the purpose and costs of indexing."]),
  ],
  units: [
    unit("S8.01-FILES", "From repeated facts to linked tables", ids("S8.01", 1, 2), [
      "A file-based approach keeps data in files managed by individual applications. Repeating a patient's address in appointment and billing files uses extra storage. If only the billing copy is updated, the two applications may report different addresses for the same patient.",
      "A relational design can store the address in Patient and put PatientID in related records. Applications retrieve the shared fact through that relationship. Central queries, constraints and access controls also reduce isolated retrieval and duplicated control code; the benefits depend on the design and its enforcement.",
    ], [table("Problem, mechanism and consequence", ["File-based problem", "Relational response", "Result"], [["Same address in several files", "One Patient row referenced by IDs", "Fewer copies of the address"], ["Only one copy updated", "Change the shared Patient value", "Related retrieval uses the same value"], ["Separate file formats", "Query linked tables through the DBMS", "Combine related data consistently"]]), worked("A patient moves house", [["Before", "Appointment and Billing each store PatientID 14 and Address '8 Oak Road'."], ["File-based update", "Billing changes to '20 Hill Road', but Appointment still gives the old address."], ["Relational design", "Patient(14, '20 Hill Road') stores the address; Appointment and Billing retain PatientID 14."], ["Check", "Both applications retrieve the address from Patient rather than updating independent address copies."]])],
      "A database does not automatically remove every duplicate fact; keys, relationships and controlled updates must be designed.",
      "Is repeating PatientID in several appointments the same redundancy problem as repeating the address?", "No. PatientID is the reference needed to link appointments to the shared patient facts."),
    unit("S8.02-TERMS", "Entities, tables, records and fields", ids("S8.02", 1), [
      "An entity is a type of real-world object or concept about which data is stored, such as Patient. A table represents occurrences of that entity. One row is a record, also called a tuple; it describes one particular patient.",
      "An attribute is a named property of the entity, such as PatientName. A field is the corresponding column in its table. Distinguish the property from one value: PatientName is the field, while 'Imani' is a value in a particular record.",
    ], [table("Patient table", ["PatientID", "PatientName", "Town"], [[14,"Imani","York"],[18,"Hugo","Leeds"]])],
      "An entity type, one entity occurrence and the value in one field are different things.",
      "In the displayed table, what do tuple and attribute refer to?", "A tuple is one patient row; an attribute is a property represented by a column, such as Town."),
    unit("S8.02-KEYS", "Choose keys for identification and retrieval", ids("S8.02", 2), [
      "A candidate key is a minimal field or combination of fields that uniquely identifies a record. One candidate is selected as the primary key; its values must be unique and not null. A composite key uses more than one field, with every component needed for uniqueness.",
      "A secondary key provides an additional way to retrieve records, such as looking up all patients in one town; it need not be unique. A foreign key stores a reference to a key in a related table. The same patient can therefore appear as the foreign-key value in several appointments.",
    ], [table("Keys in a small clinic", ["Field or fields", "Role", "Reason"], [["Patient.PatientID", "Primary key", "Chosen unique patient identifier"], ["Patient.NationalNumber", "Other candidate key", "Assumed unique and present for each patient"], ["Patient.Town", "Secondary key", "Find all patients in a town"], ["Appointment.PatientID", "Foreign key", "Identify the patient attending"]])],
      "Secondary key does not mean an unchosen candidate key; it may identify a set of matching records.",
      "Two patients share a name. Can PatientName uniquely identify every patient?", "No. A primary key must distinguish those patients; a dedicated PatientID is suitable."),
    unit("S8.02-RELATIONSHIPS", "Read relationship cardinality in both directions", ids("S8.02", 3), [
      "Relationship cardinality describes how many occurrences on one side may be associated with an occurrence on the other. Read the business rule in both directions before choosing one-to-one, one-to-many or many-to-many.",
      "If a student can join several clubs and a club can have several students, the relationship is many-to-many. A Membership table records each student-club association and gives two one-to-many relationships. The pair of identifiers can be its composite key when each membership occurs only once.",
    ], [table("Business rules determine the relationship", ["Rule", "Relationship"], [["Each pupil has one locker; each locker is assigned to at most one pupil", "One-to-one"], ["A tutor has several pupils; each pupil has one tutor", "One-to-many"], ["Students join several clubs; clubs admit several students", "Many-to-many, resolved using Membership"]])],
      "Matching column names alone do not establish a relationship; the association must follow the scenario.",
      "Why does Membership need both StudentID and ClubID?", "Together they identify which student belongs to which club; either identifier alone loses one side of the association."),
    unit("S8.02-REFERENTIAL", "Prevent references to missing records", ids("S8.02", 4), [
      "Referential integrity requires each non-null foreign-key value to match an existing referenced key value. If an appointment names PatientID 99 but no such patient exists, a declared foreign-key constraint can reject that appointment.",
      "Updates and deletions must also preserve valid links. Deleting a referenced patient can be rejected, or handled by an explicitly defined referential action. A nullable foreign key may be null where the design allows no association; it must not hold an arbitrary unmatched identifier.",
    ], [table("Patient IDs currently stored: 14 and 18", ["Proposed operation", "Check"], [["Add appointment for 14", "Reference exists"], ["Add appointment for 99", "Reject unmatched reference"], ["Delete 14 while an appointment references it", "Reject unless a permitted referential action handles the link"]])],
      "A foreign key usually permits repeated values; uniqueness is not the rule that prevents orphan records.",
      "Would PatientID 18 in two appointments violate referential integrity?", "No. Both references match patient 18; the appointments have their own identifiers."),
    unit("S8.02-INDEX", "Use an index to find matching records", ids("S8.02", 5), [
      "An index is an additional lookup structure associated with one or more fields. It relates indexed values to record locations so the DBMS can find matches without inspecting every table row in suitable queries.",
      "An index on Town can help retrieve all patients in York even when Town is not unique. The index occupies storage and must be maintained when indexed data changes. It improves an access path; it does not replace the table or guarantee that stored facts are correct.",
    ], [table("A simplified Town lookup", ["Town value", "Matching PatientID values"], [["Leeds","18, 24"],["York","14, 29, 35"]])],
      "Do not describe indexing as sorting every output automatically; query result order is specified separately.",
      "Why might an index slow an update?", "The DBMS may need to change the index as well as the underlying record."),
  ],
  practice: [
    practice(1, 1, "A garage repeats a customer's phone number in repair and invoice files. Explain two problems this can cause and describe how a linked Customer table addresses each problem.", ids("S8.01", 1, 2), ["Multiple phone-number copies consume avoidable storage.", "A Customer record can hold one shared number while repair and invoice records retain the customer reference.", "Changing only one file leaves conflicting phone numbers.", "Retrieving the number from the updated Customer record avoids separate phone-number updates."], "Pair each problem with the specific mechanism that reduces it."),
    practice(1, 2, "Identify the entity, one record and two attributes represented by Book(BookID, Title, Price), containing (7, 'Dunes', 12.50). Give the equivalent terms for record and field.", ids("S8.02", 1), ["Book is the entity type.", "The row for BookID 7 is one record.", "Title and Price are two attributes; BookID is also acceptable.", "Tuple corresponds to record, and attribute corresponds to field."], "Do not call 'Dunes' the name of a field."),
    practice(1, 3, "A school assigns each pupil a unique PupilID and a unique exam number. Names and tutor groups may repeat. Identify the candidate keys, choose a primary key, suggest a secondary key for finding tutor-group members, and explain why Attendance.PupilID is a foreign key.", ids("S8.02", 2), ["PupilID and ExamNumber are separate candidate keys under the stated uniqueness rules.", "PupilID can be chosen as the primary key; ExamNumber is also a valid choice if used consistently.", "TutorGroup is a suitable secondary key for the specified retrieval.", "Attendance.PupilID refers to the identifier of the pupil whose attendance is recorded."], "An unused candidate key is not automatically a secondary key."),
    practice(1, 4, "State the relationship in each case: every employee has one parking permit and each permit belongs to one employee; each customer places many orders and every order has one customer; each actor appears in many films and every film has many actors. Explain how to store the final relationship.", ids("S8.02", 3), ["Employee to permit is one-to-one.", "Customer to order is one-to-many.", "Actor to film is many-to-many.", "A linking table stores ActorID and FilmID for each appearance, creating two one-to-many links."], "Read both directions before assigning cardinality."),
    practice(1, 5, "Department contains IDs 3 and 6. Employee.DepartmentID is a non-null foreign key. Explain whether values 6 and 8 can be inserted, and whether two employees may both contain 3.", ids("S8.02", 4), ["Value 6 is permitted because department 6 exists.", "Value 8 must be rejected because no referenced department has that identifier.", "Two employees may reference 3 because a valid foreign-key value need not be unique."], "Check the referenced table, not uniqueness in Employee."),
    practice(1, 6, "A catalogue has 200000 products and users frequently search by Category. Explain one benefit and two costs of adding an index on Category.", ids("S8.02", 5), ["The lookup structure can locate matching products without scanning all catalogue records.", "The additional structure occupies storage.", "Changes to indexed category values require index maintenance."], "Do not promise that every possible query becomes faster."),
  ],
  authoredExamQuestions: [
    exam(1, 1, "A charity stores donor addresses separately in subscription and donation files. Staff update only the donation file when a donor moves. Explain the resulting data problem and propose a relational change, including the roles of the identifier fields.", [...ids("S8.01",1,2), ...ids("S8.02",2)], ["The same donor now has inconsistent addresses across the two applications.", "A Donor table should retain the current address for each identified donor.", "DonorID uniquely distinguishes a donor in that table.", "Subscription and Donation rows reference DonorID so their address retrieval reaches the shared donor record."], "Link the proposed table design to the stated partial-update failure."),
    exam(1, 2, "A theatre records Performer(PerformerID, Name) and Production(ProductionID, Title). Each performer can appear in several productions and each production uses several performers. Describe a suitable linking table and its keys, assuming only one role per performer per production.", ids("S8.02",1,2,3), ["An Appearance table represents the association between one performer and one production.", "It contains PerformerID and ProductionID as references to the two parent tables.", "The combined pair can uniquely identify an appearance under the one-role rule.", "Each performer can have many Appearance records and each production can have many Appearance records."], "Neither parent identifier alone distinguishes every appearance."),
    exam(1, 3, "A delivery record names DepotID 12, but Depot contains only IDs 4 and 9. An index on DepotName is also proposed to speed searches. Explain why the record should be rejected, what the index can improve, and why that index does not solve the invalid reference.", ids("S8.02",4,5), ["There is no depot row matching the supplied foreign-key value 12.", "Enforcing the reference constraint prevents a delivery being assigned to a nonexistent depot.", "A name index provides an access path to depots matching a requested name.", "Faster name lookup does not create depot 12 or enforce the identifier relationship by itself."], "Separate integrity enforcement from retrieval efficiency."),
  ],
  summary: [["Remove inconsistent copies", "Store a shared fact with its entity and reference it from related records."], ["Identify and link", "Choose a minimal unique identifier; use foreign keys for associations and secondary keys for retrieval."], ["Check the relationship", "Use business rules to determine cardinality and prevent unmatched references."], ["Plan access", "Indexes trade extra storage and update work for more efficient suitable searches."]],
};

const design = {
  title: "Entity-relationship design and normalisation",
  subtitle: "Turn business rules into an E-R diagram, then remove repeating groups, partial dependencies and transitive dependencies.",
  guidingQuestion: "Which entity should own each fact, and how can the original information still be retrieved after splitting tables?",
  diagnostic: { prompt: "An order contains several products. Does OrderID alone uniquely identify each order-product line?", answer: "No. If each product appears once per order, the pair (OrderID, ProductID) identifies the line." },
  objectives: [...objectives("S8.03", ["Use an entity-relationship diagram to document a database design."]), ...objectives("S8.04", ["Explain First Normal Form and remove repeating groups.", "Explain Second Normal Form and remove partial dependencies.", "Explain Third Normal Form and remove transitive dependencies.", "Explain why a given relation is or is not in Third Normal Form.", "Produce a normalised database design from stated data and dependencies."])],
  units: [
    unit("S8.03-ER", "Document entities, keys and relationship cardinality", ids("S8.03",1), [
      "Extract entity types from the facts that the organisation needs to store, then identify each entity's key and relevant attributes. Connect entities only when the business rules support an association. An E-R diagram records this structure rather than a sequence of processing steps.",
      "In this clinic, each appointment involves exactly one patient and one doctor. A patient or doctor may have many appointments. Appointment therefore stores both foreign keys, and its separate AppointmentID allows the same patient to visit the same doctor on different occasions.",
    ], [{ type:"reviewed-visual", title:"Clinic E-R design", asset:"/assets/course-v3/section-8/clinic-er.svg", alt:"Patient has a one-to-many relationship with Appointment. Doctor has a one-to-many relationship with Appointment. Appointment contains its own primary key and both foreign keys.", facts:["Patient(PatientID PK, PatientName).","Doctor(DoctorID PK, DoctorName).","Appointment(AppointmentID PK, PatientID FK, DoctorID FK, VisitDate).","Each appointment references one patient and one doctor; either parent can have many appointments."], review:"authored-exact-svg" }, worked("From a clinic rule to a diagram", [["Find entities", "Store patient facts in Patient, doctor facts in Doctor, and the date of a particular visit in Appointment."], ["Identify rows", "Choose PatientID, DoctorID and AppointmentID as primary keys."], ["Read both directions", "One appointment names one patient; one patient may attend many appointments. Apply the equivalent rule for Doctor."], ["Place the references", "PatientID and DoctorID are foreign keys in Appointment, on the many side of each relationship."]])],
      "A pair of matching names is not a business rule, and a data-flow arrow does not replace relationship cardinality.",
      "Why not use (PatientID, DoctorID) as the only appointment key?", "The pair can repeat on different visits, so it would not identify every appointment."),
    unit("S8.04-1NF", "1NF: one value in each field", ids("S8.04",1), [
      "First Normal Form requires atomic field values and no repeating groups. For this ordering system, a list of product entries in one order field is a repeating group. Give each product line its own row while retaining the order and customer information needed to interpret that row.",
      "Assume each product occurs at most once per order and the stored unit price is the product's current fixed price. The pair (OrderID, ProductID) identifies a line. Separating the list makes values atomic, but repeated customer and product details still remain to be addressed in later normal forms.",
    ], [table("Unnormalised order input", ["OrderID", "Customer", "Items: ProductID / name / price / quantity"], [[501,"C7 / Amina","P1 / Pen / 2 / 3; P2 / Pad / 5 / 1"],[502,"C7 / Amina","P1 / Pen / 2 / 2"]]), worked("Expand the repeating product group", [["First order, first item", "(501, C7, Amina, P1, Pen, 2, 3)"], ["First order, second item", "(501, C7, Amina, P2, Pad, 5, 1)"], ["Second order", "(502, C7, Amina, P1, Pen, 2, 2)"], ["1NF relation", "OrderData(OrderID, CustomerID, CustomerName, ProductID, ProductName, UnitPrice, Quantity)\nPRIMARY KEY: (OrderID, ProductID)"]])],
      "Splitting a list into rows does not by itself remove dependencies on part of a composite key.",
      "Why does the first order produce two rows?", "It contains two distinct product entries, and each must be represented by an atomic product-line record."),
    unit("S8.04-2NF", "2NF: depend on the whole composite key", ids("S8.04",2), [
      "Second Normal Form requires 1NF and no partial dependency of a non-key attribute on part of a candidate key. In the order example, ProductName and UnitPrice depend on ProductID alone, while CustomerID and CustomerName depend on OrderID alone. Quantity depends on the whole line key.",
      "Move the product facts to Product and the order-level facts to SalesOrder. Keep OrderLine for the association and quantity, retaining the two identifying fields as references. This decomposition removes partial dependencies but does not yet separate CustomerName from CustomerID inside SalesOrder.",
    ], [table("Stated dependencies", ["Determinant", "Dependent facts", "Destination"], [["OrderID","CustomerID, CustomerName","SalesOrder"],["ProductID","ProductName, UnitPrice","Product"],["OrderID + ProductID","Quantity","OrderLine"]]), worked("The 2NF decomposition", [["Product facts", "Product(ProductID, ProductName, UnitPrice)\nPRIMARY KEY: ProductID"], ["Order facts", "SalesOrder(OrderID, CustomerID, CustomerName)\nPRIMARY KEY: OrderID"], ["Line facts", "OrderLine(OrderID, ProductID, Quantity)\nPRIMARY KEY: (OrderID, ProductID)\nFOREIGN KEYS: OrderID to SalesOrder; ProductID to Product"], ["Check a line", "OrderLine(501, P1, 3) links to Product(P1, Pen, 2) and SalesOrder(501, C7, Amina)."]])],
      "Deleting ProductID from OrderLine would lose which product belongs to the order; keep the reference after moving product facts.",
      "Why is Quantity not stored as a single attribute of Product?", "Different orders can request different quantities of the same product; quantity belongs to the order-product association."),
    unit("S8.04-3NF", "3NF: remove transitive dependencies", ids("S8.04",3), [
      "Third Normal Form requires 2NF and, in these simple designs, no dependency of one non-key attribute on another non-key attribute. SalesOrder still contains OrderID determining CustomerID and CustomerID determining CustomerName. The customer's name is transitively dependent on the order identifier.",
      "Create Customer(CustomerID, CustomerName) and retain CustomerID as a foreign key in SalesOrder. Customer facts can then be updated in their own relation. Product and OrderLine remain unchanged; the existing keys allow the original order information to be reconstructed.",
    ], [table("Remove the transitive dependency", ["Before", "After"], [["SalesOrder(OrderID, CustomerID, CustomerName)","SalesOrder(OrderID PK, CustomerID FK)"],["CustomerName repeated across a customer's orders","Customer(CustomerID PK, CustomerName)"]]), worked("Reconstruct the original order line", [["Start with the line", "OrderLine(501, P1, 3) supplies order, product and quantity."], ["Follow the order reference", "SalesOrder(501, C7) identifies the customer."], ["Retrieve the customer", "Customer(C7, Amina) supplies the name."], ["Retrieve the product", "Product(P1, Pen, 2) supplies product name and price. All seven original line values remain available."]])],
      "Normalisation reduces particular redundancy and anomalies; it does not prove that every entered value is true.",
      "If Amina changes her name, how many Customer records require the change?", "One: the record identified by C7. Her orders continue to reference that customer."),
    unit("S8.04-DESIGN", "Judge and produce a complete 3NF design", ids("S8.04",4,5), [
      "To judge a design, name its key, state the relevant dependencies and test each normal form in order. One row per entity is not sufficient evidence of 3NF. A non-key fact can still describe another entity, producing an update, insertion or deletion anomaly.",
      "To produce a design, assign each fact to its determinant and explicitly retain primary and foreign keys. Check that every original attribute is accounted for and that a representative original record can be reconstructed. State any assumptions about uniqueness instead of inventing extra dependencies.",
    ], [table("Acceptance checks for the order design", ["Check", "Evidence"], [["1NF","Each OrderLine value describes one product line"],["2NF","Product facts and order facts moved off the composite line key"],["3NF","CustomerName depends on the Customer key in its own table"],["Information retained","Product, quantity and customer details remain linked through identifiers"]]), worked("Analyse a different relation", [["Given", "Employee(EmployeeID, EmployeeName, DepartmentID, DepartmentName). EmployeeID is the key; DepartmentID determines DepartmentName."], ["Diagnose", "DepartmentName depends on the non-key DepartmentID, so the relation fails the simple 3NF test."], ["Decompose", "Employee(EmployeeID PK, EmployeeName, DepartmentID FK)\nDepartment(DepartmentID PK, DepartmentName)"], ["Verify", "Each employee still identifies one department, whose name is stored in Department."]])],
      "A decomposition must preserve the relationships needed to recover the represented facts; unrelated fragments are not an adequate design.",
      "Does giving every row a new numeric key automatically remove a dependency between DepartmentID and DepartmentName?", "No. That dependency remains and must be addressed by assigning department facts to their own relation."),
  ],
  practice: [
    practice(2,1,"Draw an E-R diagram for a library where each Copy belongs to one Book and each Loan refers to one Copy. A book may have several copies and a copy may be loaned many times. Include primary keys, foreign keys and relationship cardinalities.",ids("S8.03",1),["Book has BookID as its primary key.","Copy has CopyID as its primary key and BookID as a foreign key.","Loan has LoanID as its primary key and CopyID as a foreign key.","Book to Copy is one-to-many.","Copy to Loan is one-to-many."],"A loan identifies a physical copy, not just the book title."),
    practice(2,2,"An order row contains OrderID 70 and a repeating Items field with (P4, quantity 2) and (P8, quantity 5). Write a 1NF relation and its two rows, assuming each product appears once per order. State its key.",ids("S8.04",1),["Use OrderItem(OrderID, ProductID, Quantity) with one item per row.","The rows are (70, P4, 2) and (70, P8, 5).","The combined (OrderID, ProductID) identifies each row."],"Retain OrderID in both item rows."),
    practice(2,3,"Registration(StudentID, CourseID, CourseTitle, Grade) has key (StudentID, CourseID). CourseID determines CourseTitle; the complete key determines Grade. Explain the 2NF violation and give the corrected relations and keys.",ids("S8.04",2),["CourseTitle depends on CourseID, which is only part of the composite key.","Create Course(CourseID, CourseTitle), keyed by CourseID.","Retain Registration(StudentID, CourseID, Grade) with its composite key.","Registration.CourseID references Course.CourseID."],"A student's grade belongs to their registration, not to Course alone."),
    practice(2,4,"Customer(CustomerID, Postcode, Town) has key CustomerID. Each postcode determines one town. Explain why the table fails 3NF and state a decomposition with its linking field.",ids("S8.04",3),["Town depends on the non-key Postcode, producing a transitive dependency from CustomerID.","Use Customer(CustomerID, Postcode) and PostcodeArea(Postcode, Town).","Customer.Postcode is a foreign key to PostcodeArea.Postcode."],"Use the stated postcode-to-town rule rather than assuming Town uniquely determines Postcode."),
    practice(2,5,"A museum stores Item(ItemID, ItemName, RoomID, RoomName). ItemID is the key and RoomID determines RoomName. Explain whether this is in 3NF and produce a design that allows a room to be recorded before any items are assigned to it.",ids("S8.04",4,5),["RoomName is transitively dependent on ItemID through RoomID, so the table is not in 3NF.","Create Room(RoomID, RoomName) with RoomID as its key.","Keep Item(ItemID, ItemName, RoomID) with ItemID as its key.","Item.RoomID references Room, while an empty room can exist as a Room record without any Item records."],"The room must have a place to store its own facts independently of an item."),
  ],
  authoredExamQuestions: [
    exam(2,1,"Draw an E-R design for a repair business. Each job concerns exactly one device and is assigned to one technician. A device can have several jobs and a technician handles several jobs. Store the completion date of each job and show all keys and cardinalities.",ids("S8.03",1),["Device has a unique DeviceID.","Technician has a unique TechnicianID.","Job has JobID and CompletionDate, plus DeviceID and TechnicianID as foreign keys.","Device has a one-to-many association with Job.","Technician has a one-to-many association with Job."],"Put the completion date on the job because a device can be repaired on different dates."),
    exam(2,2,"A table stores TeamID and a single Members field containing several member identifiers. Describe the First Normal Form problem and explain how to retain all memberships using atomic values. Assume a member can join several teams.",ids("S8.04",1),["Members contains a repeating group of identifiers rather than one atomic identifier per field value.","Represent one team-member association in each Membership(TeamID, MemberID) row.","Use both identifiers to distinguish memberships and retain multiple rows for a team or member."],"Resolving this repeating group requires atomic membership records; naming 2NF or 3NF does not describe the 1NF defect."),
    exam(2,3,"Rental(RentalID, EquipmentID, EquipmentName, DepotID, DepotName, Days) has key (RentalID, EquipmentID). RentalID determines DepotID, DepotID determines DepotName, EquipmentID determines EquipmentName, and the full key determines Days. All values are atomic. Explain the partial and transitive dependencies and produce a 3NF design with keys and references.",ids("S8.04",2,3,4,5),["EquipmentName depends on EquipmentID alone, while depot details depend on RentalID alone; these are partial dependencies on the rental-line key.","DepotName also depends transitively on RentalID through DepotID.","Use Equipment(EquipmentID PK, EquipmentName).","Use Depot(DepotID PK, DepotName).","Use RentalHeader(RentalID PK, DepotID FK to Depot).","Use RentalLine(RentalID FK to RentalHeader, EquipmentID FK to Equipment, Days), with the combined identifiers as its primary key."],"Keep Days on RentalLine and retain both references so each rental-equipment fact remains recoverable."),
  ],
  summary: [["Model first","Extract entities and read each relationship in both directions."],["Check 1NF then 2NF","Use atomic values, then separate facts that depend on only part of a composite key."],["Check 3NF","Move facts that depend on another non-key attribute to the relation identified by that attribute."],["Preserve the design","Record all primary and foreign keys and reconstruct an original example to check that no facts were lost."]],
};

const dbms = {
  title: "DBMS architecture, integrity, security and backup",
  subtitle: "Distinguish database management features and follow the developer interface and query processor through practical tasks.",
  guidingQuestion: "Which DBMS feature defines a rule, enforces it, controls access or restores lost data?",
  diagnostic: { prompt: "A foreign-key constraint rejects an appointment for a missing patient. Is this an access-permission decision?", answer: "No. It is an integrity check on the relationship; access rights decide whether the user may attempt the operation." },
  objectives: [...objectives("S8.05",["Explain DBMS data management and the role of a data dictionary.","Explain how data modelling represents organisational data.","Explain the purpose of a logical database schema.","Explain how a DBMS enforces data integrity.","Explain individual and group access rights for database security.","Explain database backup and recovery procedures."]),...objectives("S8.06",["Explain the practical use of a DBMS developer interface.","Explain the practical use of a DBMS query processor."])],
  units: [
    unit("S8.05-DICTIONARY","Data management and the data dictionary",ids("S8.05",1),[
      "A DBMS provides software services to store, retrieve and update database data. It maintains a data dictionary containing metadata: information about the database's tables, fields, types, lengths, keys and constraints rather than the ordinary records themselves.",
      "When a table or query is defined, the DBMS can consult that metadata to check field names and permitted structures. Maintaining definitions centrally reduces the risk that separate applications use conflicting assumptions about the same stored data.",
    ],[table("Metadata for an Appointment field",["Property","Definition"],[["Field name","PatientID"],["Type","INTEGER"],["Constraint","Foreign key"],["Reference","Patient.PatientID"]])],"A patient's address is application data; the permitted type and size of the address field are metadata.","Which belongs in the dictionary: a customer's balance of 42.50 or the fact that Balance has type REAL?","The field definition belongs in the dictionary; 42.50 is a value in a customer record."),
    unit("S8.05-MODELLING","Represent the organisation's data",ids("S8.05",2),[
      "Data modelling identifies the entities, attributes and relationships required by an organisation. It starts from the information and business rules, such as whether one appointment may involve several doctors, rather than from how bytes will be arranged on disk.",
      "A DBMS modelling tool can help create and inspect the relationships before they are implemented as tables. The designer must still confirm that the model matches the stated requirements; software cannot infer every business rule from field names.",
    ],[flow("From requirement to model",[["Requirement","Each pupil belongs to one tutor group."],["Entities","Pupil and TutorGroup."],["Relationship","One group may contain many pupils."],["Validate","Check with the school whether any pupil can belong to several groups."]])],"Data modelling describes what the data represents; it does not choose which individual user may edit a record.","Why ask whether pupils may belong to several tutor groups?","That rule changes relationship cardinality and may require a linking entity."),
    unit("S8.05-SCHEMA","Define the logical schema",ids("S8.05",3),[
      "The logical schema specifies the logical organisation of the database: its tables, attributes, data types, keys, relationships and constraints. Programs can use these definitions without knowing the physical disk locations of individual records.",
      "A model of pupils and groups can become Pupil(PupilID, PupilName, GroupID) and TutorGroup(GroupID, GroupName), with specified primary and foreign keys. The schema is the design being defined; the data dictionary stores metadata describing that design.",
    ],[table("A logical organisation",["Table","Primary key","Other attributes and links"],[["TutorGroup","GroupID","GroupName"],["Pupil","PupilID","PupilName; GroupID references TutorGroup"]])],"The logical schema and data dictionary are related, but they are not interchangeable names for the same object.","Must an application know the disk sector containing TutorGroup before querying it?","No. It uses the logical table and field definitions; the DBMS handles physical access."),
    unit("S8.05-INTEGRITY","Enforce valid values and relationships",ids("S8.05",4),[
      "Integrity constraints restrict invalid or inconsistent database changes. A primary key identifies records uniquely, a foreign key checks a declared reference, and field types or validation rules restrict values to a permitted domain.",
      "For an examination database, a rule can require Mark to be between 0 and 100 and CandidateID to refer to an existing candidate. The DBMS rejects changes violating those rules. A plausible but incorrectly transcribed mark can still pass them, so integrity constraints do not establish factual truth.",
    ],[table("Proposed ExamResult changes",["Change","Integrity check"],[["Duplicate ResultID","Reject duplicate primary key"],["CandidateID absent from Candidate","Reject unmatched reference"],["Mark = 145","Reject stated 0 to 100 range violation"]])],"A backup helps recovery after a failure; it does not validate a new examination mark.","Does a stored mark of 73 prove that 73 was written on the script?","No. It is within range, but it may still be the wrong value for that script."),
    unit("S8.05-SECURITY","Assign access rights to users and groups",ids("S8.05",5),[
      "Database security restricts who can access stored information and which operations are permitted. After authentication establishes identity, access rights can allow reading selected data while denying insertion, modification or deletion.",
      "Rights may be assigned to an individual account or to a group representing a role. A school can give Tutors access to contact information and the Finance group permission to update fees. Group membership must be maintained when responsibilities change.",
    ],[table("Example permission decisions",["Role","Read contact data","Update fees"],[["Tutor","Allow","Deny"],["Finance","Allow","Allow"],["Visitor","Deny","Deny"]])],"A valid login does not imply permission to modify every table.","How can a new finance officer receive the existing finance permissions?","Add the authenticated account to the appropriately configured Finance group."),
    unit("S8.05-BACKUP","Back up and recover a consistent database",ids("S8.05",6),[
      "A backup procedure creates a recoverable copy of database state. Schedule backups often enough for the acceptable data-loss interval, protect copies from the same failure as the live system, and restrict access because the copies may contain sensitive records.",
      "Recovery restores a suitable consistent backup after loss or corruption. Where the DBMS supports transaction logs, later recorded changes may be replayed to a chosen recovery point. Periodic restore tests check that the stored copies and procedure actually work.",
    ],[flow("Recover after a storage failure",[["Prepare","Take scheduled consistent backups and protect a separate copy."],["Select","Choose the last suitable backup and any supported recovery logs."],["Restore","Rebuild the database in an authorised recovery environment."],["Verify","Check integrity and expected records before resuming service."]]),worked("A failure between backups",[["Timeline","A verified backup was completed at 18:00 yesterday. The live database fails at 11:00 today."],["Backup-only recovery","Restoring that copy returns the database to its saved 18:00 state."],["Loss interval","Changes after 18:00 are not present unless another recovery source preserves them."],["Improve the procedure","Choose a shorter backup interval or supported log recovery to meet the required recovery point."]])],"A backup on the same failed disk may be lost with the live data; a successful copy job is not a restore test.","Why test a restoration before an actual emergency?","To discover unreadable copies, missing dependencies or an ineffective recovery procedure while the live database is still available."),
    unit("S8.06-DEVELOPER","Use the developer interface",ids("S8.06",1),[
      "A DBMS developer interface supplies tools for constructing database objects and applications. A developer can define tables and constraints and build forms or reports that use the database without manually implementing every interface component.",
      "For a school admissions form, the developer chooses the fields, configures validation and links controls to the appropriate data. The resulting form collects a new pupil record. Designing that form is distinct from the query processor carrying out its eventual data request.",
    ],[table("Developer task",["Task","Result"],[["Define Pupil fields and constraints","A table definition"],["Arrange entry controls","An admissions form"],["Select and format attendance information","An attendance report"]])],"The developer interface creates and configures objects; it is not the component that executes every user's query.","Which tool helps arrange fields and labels on a new data-entry form?","The DBMS developer interface or its form-design tools."),
    unit("S8.06-PROCESSOR","Follow a query through the query processor",ids("S8.06",2),[
      "A query processor interprets a submitted query, checks its syntax and references, and determines how to carry out the requested data access. It can use table definitions and available indexes when choosing a suitable execution plan.",
      "It executes the plan and produces the requested result while DBMS permissions and integrity rules apply. A staff query for overdue loans therefore involves locating, filtering and returning records; it does not require rebuilding the data-entry form each time.",
    ],[flow("Request to result",[["SQL received","Staff request LoanID values for overdue loans."],["Check","Resolve table and field names and check the permitted operation."],["Plan","Choose access steps, potentially using an index."],["Execute","Read matching records and return the selected fields."]])],"An execution plan is a way to carry out a query, not a redesign of the organisation's entities.","Who carries out a saved query when a user presses its Run button?","The query processor executes the request; the button may have been built using the developer interface."),
  ],
  practice: [
    practice(3,1,"Describe two pieces of metadata a DBMS stores for a field named BirthDate and explain one way the DBMS can use that metadata.",ids("S8.05",1),["It stores the field's data type, such as DATE.","It can record a constraint such as whether a null value is permitted.","The stored definition helps the DBMS check whether a proposed field value satisfies the declared requirements."],"Give definitions about BirthDate, not one person's date of birth."),
    practice(3,2,"A designer discovers that a patient can have several appointments and an appointment concerns one patient. Describe how data modelling represents that rule.",ids("S8.05",2),["The model identifies Patient and Appointment as entities with their relevant attributes.","It represents a one-to-many association from Patient to Appointment."],"Do not answer with account permissions or backup scheduling."),
    practice(3,3,"Describe the logical schema for Team(TeamID, TeamName) and Player(PlayerID, PlayerName, TeamID), where each player has one team. Explain why the schema need not contain disk-sector addresses.",ids("S8.05",3),["It specifies both table structures, field types and their identifying keys.","Player.TeamID is declared as a reference to Team.TeamID.","Logical definitions are separated from the DBMS's physical storage placement."],"The schema is the organisation being defined; the dictionary records metadata describing it."),
    practice(3,4,"A DBMS receives three changes: reuse an existing OrderID primary-key value, reference an absent CustomerID, and set a quantity to -3 when the rule requires at least 1. Explain the integrity reason for rejecting each.",ids("S8.05",4),["Reusing OrderID would violate the unique-record identifier constraint.","The absent customer would leave an invalid foreign-key reference.","Quantity -3 is outside the declared permitted range."],"Name the relevant constraint for each proposed change."),
    practice(3,5,"Explain how individual or group access rights can allow a receptionist to read appointment times while preventing changes to treatment notes.",ids("S8.05",5),["The receptionist account or its role group is granted read access to appointment times.","The role is denied modification rights for the treatment-note data.","The DBMS checks those permissions when the authenticated account requests an operation."],"Do not assume authentication alone provides selective permissions."),
    practice(3,6,"The latest usable backup is from 02:00. A failure occurs at 09:00 and there are no recovery logs. State the restored data state and explain two improvements to the backup procedure.",ids("S8.05",6),["The restore can recover the saved 02:00 state, with later changes absent.","More frequent consistent backups can reduce the possible lost interval.","Keeping a protected separate copy and testing restoration improves the ability to recover when the live system fails."],"A backup from 02:00 does not include changes made afterwards."),
    practice(3,7,"A school needs a new enrolment form and a formatted class-list report. Describe how the DBMS developer interface helps with these two tasks.",ids("S8.06",1),["Its form tools let the developer arrange controls and associate entries with enrolment fields.","Its report tools select and lay out the class-list information for presentation."],"Describe construction tasks rather than simply saying that the tool executes queries."),
    practice(3,8,"Describe three actions performed by a query processor after receiving a request for the names of members with unpaid fees.",ids("S8.06",2),["It interprets the request and resolves the referenced table and field definitions.","It chooses a suitable sequence of access and filtering operations.","It executes those operations and returns the matching member names."],"Do not substitute the design of the entry form for executing the request."),
  ],
  authoredExamQuestions: [
    exam(3,1,"A council adds LicenceExpiry to its Permit table. Explain what the data dictionary records, how the logical schema changes, and how the DBMS can prevent an invalid expiry value without guaranteeing that the date matches the original document.",ids("S8.05",1,3,4),["The dictionary records metadata such as LicenceExpiry's DATE type and permitted-null rule.","The logical Permit definition gains the additional attribute and any associated constraints.","A constraint can reject a value that violates the stated date or permitted-range rules.","A validly represented date could still be copied incorrectly from the document."],"Distinguish valid representation from verification against the source."),
    exam(3,2,"A research database has a Readers group and an Editors group. A technician stores all backups on the live database disk and never tests a restore. Explain how the two groups can have different rights and identify two weaknesses in the backup arrangement, with an improvement for each.",ids("S8.05",5,6),["Readers may be limited to retrieval while Editors receive authorised modification permissions.","Failure of the live disk can destroy both the database and its backup copies.","Store a protected recovery copy on storage independent of that disk.","An untested backup may be unreadable or insufficient to restore the service.","Carry out periodic restoration exercises and verify the recovered data."],"Permissions do not replace recovery copies, and recovery copies do not decide user rights."),
    exam(3,3,"A clinic models patients and visits, designs a visit-entry form, and later runs a report requesting visits in a date range. Explain the separate contributions of data modelling, the developer interface and the query processor.",[...ids("S8.05",2),...ids("S8.06",1,2)],["Data modelling identifies which patient and visit facts belong to each entity and how the entities are associated.","The developer interface is used to construct the input controls and bind them to the visit data.","The query processor interprets and plans the report's stored date-range request.","Executing that plan retrieves the qualifying visits for the report."],"Keep modelling, interface construction and request execution as distinct activities."),
  ],
  summary:[["Describe the structure","Model business facts, define a logical schema and maintain its metadata."],["Control changes","Constraints check stored values and references; rights control allowed users and operations."],["Plan recovery","Protect consistent copies and test that they restore the required state."],["Identify the tool","Use the developer interface to construct objects and the query processor to carry out requests."]],
};

const languages = {
  title:"DDL, DML and the role of SQL",
  subtitle:"Classify structural changes and record operations, and explain how SQL expresses both.",
  guidingQuestion:"Does an operation change the table definition or the data stored in that table?",
  diagnostic:{prompt:"Adding a Price column and changing one product's price both change a database. Are they the same kind of change?",answer:"No. The first changes the structure; the second changes a stored field value."},
  objectives:objectives("S8.07",["Explain the role of DDL in creating and changing database structure.","Explain the role of DML in querying and maintaining stored data.","Explain SQL as the industry-standard language for DDL and DML."]),
  units:[
    unit("S8.07-DDL","DDL changes structure",ids("S8.07",1),["Data Definition Language defines and modifies database structure. It can create a database, define a table's attributes and constraints, or alter an existing table definition. These operations determine what data the database can store.","Creating a Loan table does not add a particular loan record. Similarly, adding DueDate changes the permitted structure for loan records rather than choosing the date for one member's loan."],[table("Structural requests",["Request","DDL operation"],[["Create a named database","CREATE DATABASE"],["Define fields and constraints","CREATE TABLE"],["Add a field to an existing definition","ALTER TABLE"]])],"A new table definition is not a new row in an existing table.","Which category adds a Status field to an existing table?","DDL, because the table definition gains a field."),
    unit("S8.07-DML","DML retrieves and maintains records",ids("S8.07",2),["Data Manipulation Language works with records in the defined structure. SELECT retrieves specified information. INSERT INTO adds records, UPDATE changes stored field values, and DELETE FROM removes records.","A query can produce a result table without altering the stored rows. Updating one member's phone number changes data while leaving the Member field definitions intact. These are both DML operations in the syllabus classification."],[table("Record operations",["Intent","Command"],[["Retrieve names","SELECT"],["Add a new member","INSERT INTO"],["Correct a phone number","UPDATE"],["Remove an obsolete record","DELETE FROM"]])],"DML includes retrieval even when the stored database values are unchanged.","Does SELECT become DDL because its result looks like a table?","No. It retrieves a result from the stored data; it does not define a new persistent table here."),
    unit("S8.07-SQL","SQL expresses both kinds of operation",ids("S8.07",3),["Structured Query Language (SQL) is the industry-standard language used for both DDL and DML. The DBMS interprets SQL statements and carries out their requested changes or queries. DDL and DML describe roles within SQL rather than two alternative database products.","Determine the category from the requested effect, not from the word 'change' alone. A SQL statement that changes a column's definition is structural; one that changes the current value in that column operates on data."],[flow("Classify by effect",[["Request","Add a BirthDate attribute."],["Effect","The table definition changes: DDL."],["Second request","Set one pupil's BirthDate value."],["Second effect","A record changes: DML."]]),worked("Follow the database lifecycle",[["Define","The developer creates tables and key constraints using SQL DDL."],["Populate","Users add initial records using SQL DML."],["Use","SELECT requests return information from those records."],["Maintain","ALTER TABLE changes a definition; UPDATE changes existing values. Both are SQL, but their roles differ."]])],"SQL is not limited to SELECT statements, and DDL is not another name for a DBMS.","Can one SQL script contain both DDL and DML?","Yes. It can define a table and then insert records into it, with each statement classified by its effect."),
  ],
  practice:[
    practice(4,1,"Identify CREATE TABLE and ALTER TABLE as DDL or DML, and describe the kind of object they change.",ids("S8.07",1),["Both commands are DDL.","They create or modify a table definition, including its attributes or constraints."],"Do not describe these as editing one existing record."),
    practice(4,2,"Identify SELECT, INSERT INTO, UPDATE and DELETE FROM as DDL or DML. State which retrieves information without changing stored rows and which removes records.",ids("S8.07",2),["All four commands belong to DML.","SELECT retrieves the requested information.","DELETE FROM removes the selected records."],"Deleting a record differs from removing a column definition."),
    practice(4,3,"Explain the relationship between SQL, DDL and DML, using one structural operation and one data operation as examples.",ids("S8.07",1,2,3),["SQL supplies a common language for both definition and manipulation requests.","For example, CREATE TABLE is a definition operation that establishes a structure.","For example, UPDATE is a manipulation operation that changes data within that structure."],"Give effects as well as expanding the abbreviations."),
  ],
  authoredExamQuestions:[
    exam(4,1,"A museum adds an InsuranceValue column to Item and then sets the value for ItemID 19 to 450. Explain the SQL category needed for each step and why the two steps are different.",ids("S8.07",1,2),["Adding the column requires DDL because Item's definition is extended.","Setting the value for item 19 requires DML because an individual stored record is changed.","The structural step makes the attribute available; the record operation supplies data for it."],"Do not classify both as DML solely because both change the database."),
    exam(4,2,"A librarian runs SELECT to list overdue loans. Another staff member deletes one obsolete loan record. Describe what each operation does to stored data and explain why both belong to the same SQL category.",ids("S8.07",2,3),["The selection returns qualifying information while leaving the original loan rows in place.","The deletion removes the chosen loan row from storage.","Both are SQL DML because retrieval and record maintenance operate within the existing definition."],"A query result is not evidence that the stored schema was modified."),
    exam(4,3,"A trainee says that a DBMS uses SQL only for queries and must use a separate non-SQL language to create tables. Explain the error, giving a suitable SQL definition command and the responsibility of the DBMS.",ids("S8.07",1,3),["SQL includes data-definition statements as well as queries.","CREATE TABLE is a SQL command for establishing fields and constraints.","The DBMS processes the definition and maintains the resulting database structure."],"Explain the language's roles rather than listing unrelated DBMS security features."),
  ],
  summary:[["DDL","Define or alter the organisation of stored data."],["DML","Retrieve, insert, update or delete records within that organisation."],["SQL","Express both categories of request in one standard language."],["Classify precisely","Compare the effect on the definition with the effect on existing values."]],
};

const definitions = {
  title:"Understanding and writing SQL data definitions",
  subtitle:"Read a supplied SQL statement, then create a database, select field types, define keys and alter table structure.",
  guidingQuestion:"How does a SQL definition turn a database design into tables with enforceable constraints?",
  diagnostic:{prompt:"What distinguishes changing a table definition from changing a value in one row?",answer:"The former is DDL and affects structure; the latter is DML and affects stored data."},
  objectives:[...objectives("S8.08",["Explain the effect of a supplied SQL statement.","Explain how identifiers, types, operators or literal values affect a supplied statement."]),...objectives("S8.09",["Write a CREATE DATABASE statement.","Write CREATE TABLE using appropriate CHARACTER, VARCHAR(n), BOOLEAN, INTEGER, REAL, DATE and TIME types.","Write an ALTER TABLE statement to change a definition.","Declare a PRIMARY KEY in a table definition.","Declare a FOREIGN KEY with REFERENCES in a table definition."])],
  units:[
    unit("S8.08-READ","Read the supplied statement before explaining it",ids("S8.08",1,2),[
      "A SQL statement must be interpreted from the actual identifiers, conditions and values supplied. In a retrieval statement, SELECT identifies output expressions, FROM identifies the source and WHERE restricts rows. A changed field list can alter the columns without changing which records qualify.",
      "Read a definition statement by identifying the object created or altered, its field types and its constraints. Quoted text literals represent values rather than field names. Explain the effect of the operator or limit given; recognising a keyword alone does not determine the result.",
    ],[dataTable("books"),queryExample("read","Interpret an exact supplied query","Output Title and Price for books costing at least 10, in BookID order.")],"Do not invent a filtering value or source table that is absent from the supplied statement.","If >= 10 becomes > 10 in the example, which title is no longer returned?","River is excluded because its price is exactly 10; Atlas remains."),
    unit("S8.09-DATABASE","Create a named database",ids("S8.09",1),[
      "CREATE DATABASE creates a named database in a DBMS that supports this SQL operation. The name is an identifier, not a quoted data value. Creating the database does not by itself define its tables or populate records.",
      "After creating SchoolLibrary, the developer selects that database in the chosen DBMS interface and defines its tables. The interface command for selecting a database varies between products; the SQL statement below expresses the required creation operation.",
    ],[flow("Database before tables",[["Create","CREATE DATABASE SchoolLibrary;"],["Select in the DBMS","Choose SchoolLibrary as the active database."],["Define tables","Run the table definitions within SchoolLibrary."]])],"CREATE DATABASE and CREATE TABLE create different objects.","How many Student rows does CREATE DATABASE SchoolLibrary insert?","None. Tables and record insertions require further operations."),
    unit("S8.09-TYPES","Choose data types and define fields",ids("S8.09",2),[
      "Choose a field type from the meaning and range of its values. CHARACTER stores fixed-length character data; VARCHAR(n) stores text up to the specified maximum length. INTEGER represents whole numbers, REAL represents values with a fractional part, and BOOLEAN represents true or false.",
      "DATE and TIME represent calendar dates and times of day separately. Field names and types appear inside the CREATE TABLE brackets, separated by commas. A numeric-looking identifier may still need a text type when leading zeroes or non-arithmetic meaning must be preserved.",
    ],[table("Seven field types in Student",["Field","Type","Why"],[["StudentID","INTEGER","Whole-number identifier assigned by the school"],["Initial","CHARACTER(1)","Exactly one character"],["StudentName","VARCHAR(40)","A name of variable length"],["Active","BOOLEAN","True or false"],["Score","REAL","A score may contain a fraction"],["BirthDate","DATE","A calendar date"],["ArrivalTime","TIME","A time of day"]]),worked("Create a referenced table before its child",[["Prerequisite","SchoolLibrary has been selected in the DBMS. Tutor must exist before Student's reference to it is defined."],["Complete definitions",ddl.tables],["Read the fields","StudentID and TutorID are whole-number identifiers. The remaining fields and constraints define the permitted structure."],["Check","Both primary keys identify their own rows; Student.TutorID references Tutor.TutorID. No student records have yet been inserted."]])],"Do not use REAL for every value containing digits; dates, times and textual codes have different meanings.","A room code may be '007B'. Is INTEGER suitable?","No. VARCHAR(4) can preserve the letters and leading zeroes in that code."),
    unit("S8.09-ALTER","Alter an existing table definition",ids("S8.09",3),[
      "ALTER TABLE changes the structure of an existing table. To add Email to the Student definition, identify the existing table and supply the new field name and type after ADD. Existing student records remain present.",
      "In this example the added Email field is nullable and has no default, so existing records initially have no supplied email value. Setting an email for one student is a later UPDATE operation. The new attribute and the value in one occurrence are separate changes.",
    ],[table("Before and after ADD",["State","Student fields"],[["Before","StudentID, Initial, StudentName, Active, Score, BirthDate, ArrivalTime, TutorID"],["After","All previous fields plus Email VARCHAR(80)"]]),worked("Add a contact field",[["Existing structure","Student already exists from the preceding definition."],["DDL",ddl.alter],["Result","Email is available in the table definition. This statement does not assign a particular student's address."]])],"UPDATE changes values in defined fields; it does not add the new Email field to the schema.","Which table is changed by the displayed statement?","Student is altered; Tutor is unaffected."),
    unit("S8.09-PRIMARY","Declare the primary key",ids("S8.09",4),[
      "A PRIMARY KEY constraint declares the chosen identifier for a table. The key must distinguish every record and cannot be null. Write the selected field inside PRIMARY KEY brackets in the CREATE TABLE definition.",
      "A composite primary key lists all fields needed for identification, for example PRIMARY KEY (StudentID, ClubID) in Membership. The combination must be unique; either component may recur in other combinations. Choose the key from the stated business rules.",
    ],[table("Interpret key declarations",["Declaration","Uniqueness applies to"],[["PRIMARY KEY (StudentID)","Each StudentID value"],["PRIMARY KEY (StudentID, ClubID)","Each StudentID and ClubID pair"]])],"Declaring an INTEGER field alone does not generally declare it as the primary key.","Can Membership contain (12, A) and (12, B) under the composite declaration?","Yes. The pairs differ. A second (12, A) would duplicate the primary key."),
    unit("S8.09-FOREIGN","Declare the referenced relationship",ids("S8.09",5),[
      "FOREIGN KEY names the field or fields in the current table; REFERENCES names the related table and referenced key. In Student, FOREIGN KEY (TutorID) REFERENCES Tutor(TutorID) declares which parent identifier each non-null tutor reference must match.",
      "Create the referenced table and key first when using this teaching sequence. The child field may repeat when many students share a tutor. A foreign-key declaration enforces the link; it does not automatically assign a tutor or create the missing parent record.",
    ],[flow("Read the declaration",[["FOREIGN KEY (TutorID)","TutorID is the referencing field in Student."],["REFERENCES Tutor(TutorID)","Valid non-null values are checked against the Tutor key."],["New Student row","The chosen tutor must exist; its identifier may be shared by other students."]])],"REFERENCES must name the parent table and key, not simply repeat the child table's primary-key name.","Why does defining Student.TutorID not create a Tutor row for value 9?","The declaration only defines and checks the reference; the parent record must be inserted separately."),
  ],
  practice:[
    practice(5,1,"Explain the output columns, selected records and ordering of the supplied SQL. State how replacing 'Reference' with 'Fiction' changes the qualifying titles.",ids("S8.08",1,2),["The output contains Title from Book.","Only Reference records qualify and they are sorted by increasing Price, giving Map then Atlas.","Changing the literal to Fiction instead selects Orbit then River."],"Read the quoted category and ORDER BY field from the actual statement.",{code:"SELECT Title FROM Book WHERE Category = 'Reference' ORDER BY Price;",codeCaption:"Supplied query; use the Book data below.",codeLabel:"Supplied SQL query",table:dataTable("books")}),
    practice(5,2,"Write an SQL statement to create a database named SportsCentre. State whether it creates any Booking records.",ids("S8.09",1),["CREATE DATABASE SportsCentre;","It does not create Booking records; a table definition and record insertions are separate operations."],"Use the database identifier requested, without confusing it with a table name.",{answerCode:"CREATE DATABASE SportsCentre;"}),
    practice(5,3,"Write CREATE TABLE for Event with EventID (whole number), Code (one character), EventName (up to 30 characters), Confirmed (true/false), Duration (fractional hours), EventDate (calendar date) and StartTime (time of day). Use the seven syllabus data types.",ids("S8.09",2),["EventID uses INTEGER in the Event table definition.","Code uses CHARACTER(1).","EventName uses VARCHAR(30).","Confirmed uses BOOLEAN.","Duration uses REAL.","EventDate uses DATE.","StartTime uses TIME, with valid comma-separated field definitions inside CREATE TABLE brackets."],"Each type must match the field's meaning; do not quote type names as data values.",{answerCode:ddl.practiceTable}),
    practice(5,4,"Write DDL to add Room, containing at most 12 characters, to the existing Event table. Explain why an UPDATE statement is insufficient.",ids("S8.09",3),["ALTER TABLE Event ADD Room VARCHAR(12);","The new field must first be introduced into the definition; UPDATE only assigns existing fields."],"Adding a column and filling its values are distinct operations.",{answerCode:ddl.practiceAlter}),
    practice(5,5,"Write a Locker table definition containing LockerID as INTEGER and Location as VARCHAR(30), making LockerID its primary key. State the two requirements this identifier must satisfy.",ids("S8.09",4),["The definition declares PRIMARY KEY (LockerID).","LockerID values must be unique across Locker records.","A record must not have a null LockerID."],"Do not substitute a unique-looking example value for a declared key constraint.",{answerCode:ddl.practiceKey}),
    practice(5,6,"Locker(LockerID) already has its primary key. Write Allocation with integer AllocationID as primary key and integer LockerID as a foreign key to Locker. Explain whether several allocations can reference the same locker under these constraints alone.",ids("S8.09",5),["Allocation defines its two integer fields and its own AllocationID primary key.","FOREIGN KEY (LockerID) REFERENCES Locker(LockerID) declares the parent link.","Repeated LockerID references are permitted unless an additional uniqueness rule forbids them."],"The referencing field and the referenced table/key must all be named.",{answerCode:ddl.practiceForeign}),
  ],
  authoredExamQuestions:[
    exam(5,1,"Describe the structure created by the supplied statement. Explain the length limit on AccountName, the meaning of Verified and the constraint on AccountID.",[...ids("S8.08",1,2),...ids("S8.09",2,4)],["An Account table is defined with AccountID, AccountName and Verified attributes.","AccountName holds variable-length text up to 25 characters.","Verified stores a Boolean truth value.","AccountID is the declared identifier, requiring distinct non-null values."],"This statement defines storage; it does not populate an account.",{code:"CREATE TABLE Account (AccountID INTEGER, AccountName VARCHAR(25), Verified BOOLEAN, PRIMARY KEY (AccountID));",codeCaption:"Supplied SQL definition",codeLabel:"Supplied SQL definition"}),
    exam(5,2,"Write SQL definitions for Venue(VenueID, VenueName) and Booking(BookingID, VenueID, BookingDate, Confirmed). Both ID fields in Booking and VenueID in Venue are integers; venue names contain at most 50 characters. Use suitable date and Boolean types, declare each primary key and link Booking to Venue.",ids("S8.09",2,4,5),["Venue is created with integer VenueID and VARCHAR(50) VenueName.","VenueID is declared as the Venue primary key.","Booking is created with integer BookingID and VenueID.","BookingDate is DATE and Confirmed is BOOLEAN.","BookingID is the Booking primary key.","Booking.VenueID is declared as a foreign key referencing Venue.VenueID, after the parent definition exists."],"Keep the venue reference on Booking, where several bookings can name one venue.",{answerCode:ddl.examTables}),
    exam(5,3,"The Booking table already exists. Write SQL to add a Cost field that can contain fractional amounts. Explain how this differs from assigning 24.50 to one booking and whether creating a new database is required.",ids("S8.09",1,3),["ALTER TABLE Booking ADD Cost REAL;","The statement adds the field definition; assigning one booking's amount would be a subsequent data update.","A new database is not needed to alter this existing table."],"Use the existing table name rather than CREATE DATABASE Booking.",{answerCode:ddl.examAlter}),
  ],
  summary:[["Read exact SQL","Identify the object, names, operators and values actually supplied."],["Define fields","Match whole numbers, fractional values, text, truth values, dates and times to appropriate types."],["Declare relationships","State primary and foreign-key constraints explicitly and create the referenced definition first."],["Alter structure","Use ALTER TABLE for definition changes and a separate data operation to assign values."]],
};

const manipulation = {
  title:"Querying and maintaining data with SQL DML",
  subtitle:"Select, filter, sort, group and join records, calculate aggregates, then insert, delete and update precisely identified rows.",
  guidingQuestion:"Which rows and columns should a query return, and which stored records should a maintenance statement change?",
  diagnostic:{prompt:"What does a foreign key contribute when records from two related tables are combined?",answer:"It identifies the related parent record so a join condition can match the relevant keys."},
  objectives:[...objectives("S8.10",["Write SELECT and FROM clauses for specified output fields.","Use WHERE to filter records with the required condition.","Use ORDER BY to sort query results.","Use GROUP BY to calculate one result per group.","Use INNER JOIN with ON across at most two tables.","Use SUM, COUNT and AVG and interpret their results."]),...objectives("S8.11",["Write INSERT INTO to add a complete record.","Write DELETE FROM to remove specified records.","Write UPDATE with SET to change specified field values."])],
  units:[
    unit("S8.10-SELECT","Choose the result columns and source",ids("S8.10",1),["SELECT lists the fields or expressions required in the result, while FROM names the source table. Returning MemberName alone does not return MemberID or Active. Reading a result leaves the original Member records unchanged.","Use the Member and Loan data in this lesson to trace each request. Each example states any required ordering explicitly; without ORDER BY, a DBMS need not return records in insertion or primary-key order."],[dataTable("library"),queryExample("select","Retrieve member names","Display only MemberName, keeping MemberID order for an exact result check.")],"SELECT * requests every column; use a named field list when the task requests only specific fields.","Does SELECT MemberName FROM Member delete the other columns?","No. It chooses result columns without modifying the stored table."),
    unit("S8.10-WHERE","Filter rows using a Boolean condition",ids("S8.10",2),["WHERE retains only records for which the condition is true. Combine comparisons with AND when all conditions must hold, or OR when an alternative is sufficient. Parentheses make the intended grouping explicit in compound expressions.","The Loan example requires an unreturned loan and a fee of at least 3. Loan 202 has a sufficient fee but is returned; loan 201 is unreturned but its fee is only 2. Neither satisfies both conditions."],[dataTable("library",1),queryExample("filter","Apply both conditions","Find LoanID and Fee for unreturned loans whose fee is at least 3.")],"Do not replace AND with OR when every condition is required; doing so changes which records qualify.","Why does loan 205 qualify?","Returned is FALSE and its fee of 3 meets the inclusive lower bound."),
    unit("S8.10-ORDER","Sort the returned records",ids("S8.10",3),["ORDER BY arranges result rows by the specified field or expression. ASC means increasing order and is the default; DESC means decreasing order. Sorting changes result presentation rather than the stored values.","Multiple sort fields are applied in sequence: sort by the first field, then use the next field for ties. The example sorts fees from largest to smallest and uses LoanID ascending to make any equal-fee ordering predictable."],[resultTable("sort"),queryExample("sort","State both sort directions","List LoanID and Fee by descending Fee, then ascending LoanID.")],"WHERE decides which records qualify; ORDER BY does not filter them out.","With Fee ASC, would the loan with fee 0 appear first or last?","First, because ascending numeric order starts with the smallest fee."),
    unit("S8.10-GROUP","Form groups before calculating group results",ids("S8.10",4),["GROUP BY places records sharing the grouping values into the same group. An aggregate can then calculate one result for each group. Grouping loans by MemberID lets COUNT(*) report the number of loans for each represented member.","Include non-aggregated selected fields in GROUP BY so each returned value has a defined meaning for the group. ORDER BY can subsequently arrange the grouped results; it does not create the groups. A member with no Loan row does not appear in a grouping of Loan alone."],[resultTable("group"),queryExample("group","Count loans per member","Group the five Loan records by MemberID and count rows in each group.")],"Selecting an arbitrary LoanID beside a member's aggregate would not identify the whole group; use the grouped identifier instead.","Why is Dara absent from this Loan grouping?","MemberID 4 has no Loan records, so it contributes no group."),
    unit("S8.10-JOIN","Match records from two tables with INNER JOIN",ids("S8.10",5),["An INNER JOIN combines row pairs satisfying its ON condition. Here Member.MemberID = Loan.MemberID connects each loan to its member. Qualify shared field names with the table name to make the intended reference unambiguous.","A member with two loans contributes two joined rows, while a member with no matching loan contributes none. WHERE may further filter the joined rows. These AS SQL tasks use at most two tables; use an explicit INNER JOIN and a separate ON matching condition."],[table("Matched pairs in the library",["MemberName","Matching LoanID values"],[["Asha","201, 202"],["Ben","203, 205"],["Chen","204"],["Dara","No matching loan"]]),queryExample("join","Trace a two-table join","Retrieve each member name beside the LoanID of each matching loan, ordered by LoanID.")],"A join is not a one-row-per-member list: repeated matching child records produce repeated parent values.","Why is Asha shown twice in the result?","Two different Loan rows contain her MemberID, so two row pairs match the ON condition."),
    unit("S8.10-AGGREGATES","Calculate SUM, COUNT and AVG",ids("S8.10",6),["SUM adds the numeric values of an expression, COUNT(*) counts records, and AVG calculates the mean of the included non-null values. Without GROUP BY, an aggregate query calculates one overall result for the selected records.","For the five library fees, 2 + 4 + 6 + 0 + 3 = 15, with five records and a mean of 3. A null denotes a missing value: COUNT(Fee), SUM(Fee) and AVG(Fee) ignore null fees, whereas COUNT(*) still counts their rows. Zero is a known numeric value and remains included."],[resultTable("aggregate"),queryExample("aggregate","Calculate the same result by hand","Return total fees, number of Loan records and mean fee over all five loans."),{...resultTable("nullAggregate"),title:"If a separate fee sample contains 2, NULL and 4",preserve:true}],"COUNT(*) and COUNT(Fee) can differ when some Fee values are null; do not treat a missing value as zero.","For fees 2, 4 and 0, what is AVG(Fee)?","It is 2: the total 6 is divided by all three known values, including zero."),
    unit("S8.11-INSERT","Insert values into named fields",ids("S8.11",1),["INSERT INTO adds a record. Name the target fields and supply the corresponding VALUES in the same order. Text literals use single quotes; numeric and Boolean values are written according to their types.","Check the new primary key and any foreign-key values before insertion. The library example adds MemberID 5 with the name Elena and Active TRUE. It does not alter an existing member's record, and it must fail if that primary key is already present."],[flow("Insert one member",[["Target fields","MemberID, MemberName, Active"],["Values","5, 'Elena', TRUE"],["Result","One new Member row, subject to its constraints."]]),worked("Add a member",[["Initial state","The Member table contains IDs 1 to 4."],["Statement",sql.insert.sql],["Check","MemberID 5 now stores Elena and TRUE; the four existing records remain."]])],"Do not swap the values for MemberName and Active; field order and value order must agree.","Can the same statement be repeated unchanged when MemberID is a primary key?","No. The second insertion would duplicate MemberID 5."),
    unit("S8.11-DELETE","Delete only the intended records",ids("S8.11",2),["DELETE FROM removes complete records from the named table. WHERE selects the records to remove. To remove the completed loan with LoanID 204, match that identifier rather than a member identifier shared by several loans.","Without a WHERE condition, deletion targets all rows in the table, subject to constraints. Check the intended rows first with a corresponding SELECT. Removing a referenced parent may be rejected by foreign-key constraints; this example removes the child Loan record."],[table("Loan IDs before and after deletion",["Before","After deleting LoanID 204"],[["201, 202, 203, 204, 205","201, 202, 203, 205"]]),worked("Remove a selected loan",[["Check the target","SELECT LoanID FROM Loan WHERE LoanID = 204;"],["Statement",sql.delete.sql],["Confirm","Only record 204 is removed; the other four loans remain."]])],"DELETE removes the row, not just the value in one of its fields.","Would WHERE MemberID = 1 remove only loan 201?","No. It matches both 201 and 202 in the supplied data."),
    unit("S8.11-UPDATE","Change fields while keeping the record",ids("S8.11",3),["UPDATE names the table, SET supplies the new field values, and WHERE selects the affected records. Updating Returned to TRUE for LoanID 203 leaves that loan's identity, member and fee in place.","A missing or incorrect WHERE condition can affect unintended records. Decide whether the business task requires changing a value or removing a record, then verify both the affected rows and the values that should remain unchanged."],[table("Loan 203 before and after UPDATE",["State","LoanID","MemberID","Fee","Returned"],[["Before",203,2,6,"FALSE"],["After",203,2,6,"TRUE"]]),worked("Record a returned loan",[["Target","Loan 203 has been returned; other loans must retain their current status."],["Statement",sql.update.sql],["Verify","Loan 203 remains in the table with Returned TRUE. Loan 205 for the same member remains FALSE."]])],"Filtering by MemberID 2 instead of LoanID 203 would also change loan 205.","Which clause says what to change, and which says which rows to change?","SET provides the replacement value; WHERE restricts the target rows."),
  ],
  practice:[
    practice(6,1,"Write a query returning Title and Category for every Book, ordered by BookID. State the number of result columns.",ids("S8.10",1),["SELECT names Title and Category only.","FROM identifies Book and ORDER BY uses BookID.","The result has two columns."],"Listing BookID in ORDER BY does not require including it in the output.",{table:dataTable("books"),...sqlAnswer("qSelect")}),
    practice(6,2,"Write a query listing titles of Fiction books priced at least 8, in BookID order. Use the supplied Book data and state the returned titles.",ids("S8.10",2),["The condition compares Category with the quoted text 'Fiction'.","AND combines that test with the inclusive comparison Price >= 8.","SELECT Title FROM Book returns Orbit then River under the specified ordering."],"Both conditions must hold.",{table:dataTable("books"),...sqlAnswer("qFilter")}),
    practice(6,3,"Write a query returning Title and Price from Book in decreasing price order, with titles in alphabetical order when prices tie. State the first returned title.",ids("S8.10",3),["ORDER BY uses Price DESC as the first sort field.","Title ASC is the second ordering criterion.","The named Title and Price columns come from Book; Atlas is first."],"Give the descending direction explicitly.",{table:dataTable("books"),...sqlAnswer("qSort")}),
    practice(6,4,"Write a query giving each Book category and the sum of its listed book prices, with categories alphabetically ordered. Calculate both totals from the supplied data.",ids("S8.10",4),["The result selects Category and SUM(Price) from Book.","GROUP BY Category produces a separate total for each category, and ORDER BY Category sorts those results.","Fiction totals 18 and Reference totals 20."],"ORDER BY alone cannot calculate a separate category total.",{table:dataTable("books"),...sqlAnswer("qGroup")}),
    practice(6,5,"Write a two-table INNER JOIN returning each book Title and sold Quantity for Sale records with Quantity at least 3. Order by SaleID and state the two output rows.",ids("S8.10",5),["Book is explicitly INNER JOINed to Sale.","ON matches Book.BookID with Sale.BookID.","The output names Book.Title and Sale.Quantity, filtered by Sale.Quantity >= 3 and ordered by Sale.SaleID.","The results are Atlas with 3 and River with 4."],"The matching-key condition belongs after ON; the quantity condition is a row filter.",{tables:databases.books.tables.map((_,i)=>dataTable("books",i)),...sqlAnswer("qJoin")}),
    practice(6,6,"Write one query calculating the number of Sale records, total Quantity and mean Quantity. Calculate the three results from the displayed Sale table.",ids("S8.10",6),["COUNT(*) counts the five Sale rows.","SUM(Quantity) totals the quantities to 12.","AVG(Quantity) gives 12 divided by 5, which is 2.4.","All three expressions are selected from Sale in one query."],"COUNT counts rows here, not the units sold.",{table:dataTable("books",1),...sqlAnswer("qAggregate")}),
    practice(6,7,"Stock(StockID INTEGER PRIMARY KEY, ItemName VARCHAR(30), Quantity INTEGER) contains IDs 30 and 31. Write an INSERT adding ID 32, ItemName 'Stand' and Quantity 4, using an explicit field list.",ids("S8.11",1),["INSERT INTO names Stock and the fields StockID, ItemName and Quantity in the intended order.","VALUES supplies 32, 'Stand' and 4 in that order."],"The quoted item name is a value, not a field identifier.",sqlAnswer("qInsert")),
    practice(6,8,"Stock contains (30, 'Cable', 6) and (31, 'Adapter', 2). Write SQL to remove only StockID 31. Explain the effect of omitting WHERE.",ids("S8.11",2),["DELETE FROM Stock WHERE StockID = 31; removes the Adapter record.","Without WHERE, the statement would target both Stock records."],"Use the record identifier so the Cable record remains.",sqlAnswer("qDelete")),
    practice(6,9,"Stock contains (30, 'Cable', 6) and (31, 'Adapter', 2). Write SQL to change the quantity of StockID 30 to 8. State which data in record 30 remains unchanged.",ids("S8.11",3),["UPDATE Stock SET Quantity = 8 WHERE StockID = 30;","StockID 30 and ItemName 'Cable' remain unchanged; record 31 is unaffected."],"Do not replace the update with deletion and reinsertion.",sqlAnswer("qUpdate")),
  ],
  authoredExamQuestions:[
    exam(6,1,"Write a query returning CategoryName and ProductName for available products priced at least 5. Use the two supplied tables, join the related keys and show the most expensive qualifying product first. State the returned rows.",ids("S8.10",1,2,3,5),["The selection requests Category.CategoryName and Product.ProductName.","Category and Product are combined with an explicit INNER JOIN.","ON compares their CategoryID fields.","The filter requires both Product.Available = TRUE and Product.Price >= 5.","Descending Product.Price puts the most expensive qualifying row first.","The result is (Accessories, Mouse), followed by (Stationery, Notebook)."],"The unavailable Cable must not be returned even though its price exceeds 5.",{tables:databases.shop.tables.map((_,i)=>dataTable("shop",i)),...sqlAnswer("examJoin")}),
    exam(6,2,"Write one SQL query returning each payment Branch, its number of payments, total Amount and mean Amount. Sort the groups by decreasing mean. Give the two result rows for the supplied data.",ids("S8.10",3,4,6),["The result identifies Branch and applies COUNT(*), SUM(Amount) and AVG(Amount) to Payment.","GROUP BY Branch separates the two branches' records.","ORDER BY AVG(Amount) DESC places the larger branch mean first.","North has count 2, total 30 and mean 15.","South has count 3, total 30 and mean 10."],"Equal totals do not imply equal means when group sizes differ.",{table:dataTable("payments"),...sqlAnswer("examGroup")}),
    exam(6,3,"Reservation(ReservationID INTEGER PRIMARY KEY, GuestName VARCHAR(30), Confirmed BOOLEAN) initially contains only (80, 'Tariq', TRUE). Write SQL to add (81, 'Nora', FALSE), confirm reservation 81, then remove reservation 80. State the final record and explain why each maintenance filter must use the correct identifier.",ids("S8.11",1,2,3),["The insertion supplies ReservationID 81, GuestName 'Nora' and Confirmed FALSE in matching fields.","UPDATE sets Confirmed to TRUE.","Its WHERE condition selects ReservationID 81.","DELETE FROM targets Reservation.","Its WHERE condition selects ReservationID 80.","The remaining record is (81, 'Nora', TRUE); correct identifier filters prevent changing or deleting the other reservation."],"Confirmation changes a field; removing the obsolete reservation deletes a different row.",sqlAnswer("examMaintain")),
  ],
  summary:[["Specify a result","Choose columns, source tables and row conditions, then state any required ordering."],["Combine and summarise","Match related keys with INNER JOIN; use GROUP BY when aggregates are needed per group."],["Check calculations","Count records or known values as requested and compute totals and means over the correct set."],["Maintain precisely","Match INSERT fields to values, use DELETE for records and UPDATE for fields, and verify the target condition."]],
};

const authoredLessons = [concepts, design, dbms, languages, definitions, manipulation];

export function authorSection8Lesson(source) {
  if (source.section === 8) {
    const index = source.syllabusIds.includes("S8.10") ? 5 : source.syllabusIds.includes("S8.08") ? 4 : source.originalLesson - 39;
    const authored = structuredClone(authoredLessons[index]);
    if (!authored) throw new Error(`Missing S8 lesson for ${source.syllabusIds}`);
    return {
      ...source, ...authored, units: authored.units.map(addSection8Visual), summaryMode: "authored",
      teachingCheckpoints: ["Attempt each knowledge-unit check before revealing the answer.", "Trace the supplied example, then attempt the practice and independent exam questions.", ...(index >= 4 ? ["For SQL, compare the exact result or changed records with the specified data and constraints."] : [])],
      sources: [
        "Cambridge 9618 2027–2029 syllabus, sections 8.1–8.3: https://www.cambridgeinternational.org/Images/721397-2027-2029-syllabus.pdf",
        "Original database scenarios, SQL examples, practice questions and marking points.",
      ],
    };
  }
  if (source.kind !== "review" || source.paper !== 1) return source;
  const objectiveIds = source.objectives.filter(([id]) => id.startsWith("S8.")).map(([id]) => id);
  const review = unit("REVIEW-S8", "Section 8: Databases", objectiveIds, [
    "Start with the information and business rules: identify entities, choose candidate and primary keys, then show relationship cardinalities. Diagnose repeated data and dependency problems before decomposing tables into 3NF. Retain foreign keys that allow the original facts to be reconstructed.",
    "Connect the design to its DBMS implementation. The dictionary describes fields and constraints; access rights and recovery procedures protect use and availability. Read or write DDL to define the structure, and DML to retrieve or maintain records. Trace SQL against the actual data, including join matches, grouped totals and the rows targeted by a maintenance condition.",
  ], [table("Retrieve and apply the S8 methods", ["Focus", "Evidence to produce"], [["File limitations and relational concepts", "Name a repeated fact and explain the relevant mechanism or key."],["E-R and normalisation", "Draw both cardinalities, state dependencies and retain linked 3NF relations."],["DBMS features and tools", "Connect a named facility to the work it performs."],["DDL and SQL interpretation", "Define fields and constraints, or explain a supplied statement precisely."],["DML", "Write a query and exact result, or verify the changed and unchanged records."]]), queryExample("reviewQuery", "Count outstanding loans by member", "Use the library data to retrieve each member with an unreturned loan and count only their unreturned loans.")], "A correctly named SQL command still needs the correct fields, condition and related keys.", "Why does an INNER JOIN omit a member with no matching Loan record?", "There is no pair of rows for that member satisfying the ON condition.");
  review.syllabusId = "REVIEW-1-8";
  const reviewQuestions = [
    question("REV-P1-S8-Q1", "A school stores each pupil's address in separate club files. Pupil(PupilID, PupilName, Address) and Membership(PupilID, ClubID) are proposed; Club(ClubID, ClubName) already exists. Explain how the design reduces inconsistent addresses, state the Membership key assuming one membership per pupil per club, and describe the two relationships and referential-integrity rules.", ["S8.01.R","S8.02.R","S8.03.R"], ["One Pupil row stores the address, so an address update need not be repeated in each club file.","The pair (PupilID, ClubID) uniquely identifies a Membership row.","Pupil to Membership and Club to Membership are each one-to-many.","Each Membership foreign key must match an existing identifier in its referenced Pupil or Club table."], "Neither foreign key alone uniquely identifies a membership."),
    question("REV-P1-S8-Q2", "Parcel(ParcelID, DepotID, DepotName) has atomic values and primary key ParcelID. Each depot has one name and handles many parcels. Explain why the table is not in 3NF, then give a 3NF design with keys and explain how to recover a parcel's depot name.", ["S8.04.R"], ["DepotName depends on the non-key DepotID, creating a transitive dependency from ParcelID.","Use Parcel(ParcelID PK, DepotID FK) and Depot(DepotID PK, DepotName).","Match Parcel.DepotID with Depot.DepotID to recover the depot name for each parcel."], "Splitting tables without retaining DepotID in Parcel loses the relationship."),
    question("REV-P1-S8-Q3", "A developer uses a DBMS interface to define Courier(CourierID INTEGER, CourierName VARCHAR(30), PRIMARY KEY (CourierID)). Explain the roles of the developer interface, data dictionary and query processor. Identify the language category used to create this table and state what the definition permits and prevents.", ["S8.05.R","S8.06.R","S8.07.R","S8.08.R","S8.09.R"], ["The developer interface provides tools through which the developer submits definitions or builds the application.","The dictionary records metadata such as Courier's fields, data types and key constraint.","The query processor interprets and plans submitted queries and coordinates their execution.","CREATE TABLE is SQL DDL and defines a structure without inserting courier records.","CourierName can contain up to 30 characters; the CourierID primary key forbids duplicate and null identifier values."], "The dictionary contains metadata rather than the courier records themselves."),
    question("REV-P1-S8-Q4", "Using Member and Loan, write a query returning each member name and number of unreturned loans, grouped by MemberID and MemberName and ordered by MemberID. State the result. Then write SQL marking LoanID 205 as returned and explain why that update must not identify the loan by MemberID alone.", ["S8.10.R","S8.11.R"], ["INNER JOIN matches Member.MemberID with Loan.MemberID and WHERE selects Returned = FALSE.","SELECT requests MemberName and COUNT(*), grouped by the specified member fields and ordered by MemberID.","The query returns (Asha, 1) and (Ben, 2).","UPDATE Loan SET Returned = TRUE WHERE LoanID = 205; changes only the specified loan.","A MemberID 2 filter would also target Ben's LoanID 203."], "Run the query on the supplied initial data before applying the update.", {tables:databases.library.tables.map((_,i)=>dataTable("library",i)),answerCode:sql.reviewQuery.sql + "\n\nUPDATE Loan SET Returned = TRUE WHERE LoanID = 205;",answerTable:resultTable("reviewQuery")}),
  ];
  return { ...source, units:source.units.map((u)=>u.heading === "Section 8: Databases" ? review : u), practice:[...source.practice.filter((q)=>q.id !== "V3-Q-L045-02"),...reviewQuestions] };
}
